//! 🎟️ Genuine embedding configuration declares independent full policies and finite original operation currency.
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress,ValueError,ValueRefusalKind};
use semio_framework_value_derive::{FromValue,ToValue};
use crate::GuestRelayWakeReceiptReceiver;
#[derive(Clone,Copy,Debug,PartialEq,Eq,serde::Serialize,serde::Deserialize,FromValue,ToValue)]
#[serde(deny_unknown_fields)]
pub struct GuestRelayDriverPolicy{pub root:super::GuestRelayRootPolicy,pub admission:RetainedCloneGrant,pub drive:RetainedCloneGrant,pub wake:RetainedCloneGrant,pub operation:RetainedCloneGrant}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub struct GuestRelayDriverTurnGrant{pub epoch:u64,pub grant:RetainedCloneGrant}
/// 🧮️ Only acknowledged original effects debit this finite operation treasury; no automatic currency renewal exists.
pub struct GuestRelayDriverTreasury{policy:GuestRelayDriverPolicy,original_remaining:RetainedCloneGrant,next_epoch:u64,held:Option<GuestRelayDriverTurnGrant>}
impl GuestRelayDriverTreasury{
 pub fn new(policy:GuestRelayDriverPolicy)->Self{Self{policy,original_remaining:policy.operation,next_epoch:1,held:None}}
 pub fn policy(&self)->GuestRelayDriverPolicy{self.policy}
 pub fn original_remaining(&self)->RetainedCloneGrant{self.original_remaining}
 pub fn terminal_is_empty(&self)->bool{self.held.is_none()}
 pub fn record_admission(&mut self,progress:RetainedCloneProgress)->Result<(),ValueError>{if self.held.is_some(){return Err(refusal("original driver admission cannot overlap its held turn"))}if !progress.fits(self.policy.admission){return Err(refusal("original driver admission receipt exceeds independently supplied admission policy"))}self.debit(progress)}
 pub fn begin_turn(&mut self)->Result<Option<GuestRelayDriverTurnGrant>,ValueError>{self.begin_policy_turn(self.policy.wake)}
 pub fn begin_drive_turn(&mut self)->Result<Option<GuestRelayDriverTurnGrant>,ValueError>{self.begin_policy_turn(self.policy.drive)}
 fn begin_policy_turn(&mut self,policy:RetainedCloneGrant)->Result<Option<GuestRelayDriverTurnGrant>,ValueError>{if self.held.is_some(){return Ok(None)}let grant=intersect(policy,self.original_remaining);if grant.maximum_items==0{return Ok(None)}let epoch=self.next_epoch;self.next_epoch=self.next_epoch.checked_add(1).ok_or_else(||refusal("original driver epoch overflow"))?;let turn=GuestRelayDriverTurnGrant{epoch,grant};self.held=Some(turn);Ok(Some(turn))}
 pub fn return_turn(&mut self,turn:GuestRelayDriverTurnGrant,progress:RetainedCloneProgress)->Result<(),ValueError>{if self.held!=Some(turn)||!progress.fits(turn.grant){return Err(refusal("original driver returned receipt does not match its held authority"))}self.debit(progress)?;self.held=None;Ok(())}
 fn debit(&mut self,progress:RetainedCloneProgress)->Result<(),ValueError>{if !progress.fits(self.original_remaining){return Err(refusal("original driver receipt exceeds finite operation currency"))}self.original_remaining.maximum_items-=progress.copied_items;self.original_remaining.maximum_copy_bytes-=progress.copied_bytes;self.original_remaining.maximum_capacity_bytes-=progress.retained_capacity_bytes;self.original_remaining.maximum_release_bytes-=progress.released_bytes;Ok(())}
}
impl Drop for GuestRelayDriverTreasury{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original driver treasury reached Drop with an unacknowledged turn");}}
pub(super) fn intersect(a:RetainedCloneGrant,b:RetainedCloneGrant)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:a.maximum_items.min(b.maximum_items),maximum_copy_bytes:a.maximum_copy_bytes.min(b.maximum_copy_bytes),maximum_capacity_bytes:a.maximum_capacity_bytes.min(b.maximum_capacity_bytes),maximum_release_bytes:a.maximum_release_bytes.min(b.maximum_release_bytes),maximum_depth:a.maximum_depth.min(b.maximum_depth)}}
fn refusal(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}

/// 🏦️ Supplies wake turns from one genuine finite driver treasury and acknowledges their exact original return.
pub struct GuestRelayWakeDriver{pub original:semio_framework_value::retirement::controlled::RetainedOwnerGate<WakeDriverState>}
enum DriverCheckout{Context{slot:usize,generation:u64,turn:GuestRelayDriverTurnGrant},Wake{slot:usize,generation:u64,turn:GuestRelayDriverTurnGrant},Actor{input:semio_framework_actor::RetainedTurnInput,turn:GuestRelayDriverTurnGrant,budget:semio_framework::kernel::Budget}}
struct WakeDriverState{treasury:GuestRelayDriverTreasury,checkout:Option<DriverCheckout>,root:super::GuestRelayOriginalRoot,actor_returned:Option<semio_framework_actor::RetainedTurnReceipt>,cancelled:Box<dyn Fn()->bool+Send+Sync>}
impl GuestRelayWakeDriver{
 pub fn new(policy:GuestRelayDriverPolicy,original_clock:fn()->Option<u64>,original_cancelled:Box<dyn Fn()->bool+Send+Sync>)->Result<Self,ValueError>{let root=super::GuestRelayOriginalRoot::new(policy.root,original_clock,policy.operation)?;Ok(Self{original:semio_framework_value::retirement::controlled::RetainedOwnerGate::new(WakeDriverState{treasury:GuestRelayDriverTreasury::new(policy),checkout:None,root,actor_returned:None,cancelled:original_cancelled})})}
 fn admit_original_step(original:&mut WakeDriverState)->Result<bool,semio_framework_job::OriginalTurnFailure>{if original.root.ready(){return Ok(true)}if original.checkout.is_some(){return Ok(false)}let policy=original.treasury.policy().admission;let Some(turn)=original.treasury.begin_policy_turn(policy)?else{return Ok(false)};let input=original.root.issued_input(turn.epoch)?;let budget=match original.root.issued_budget(input,turn.grant){Ok(budget)=>budget,Err(error)=>{original.treasury.return_turn(turn,Default::default())?;return Err(error.into())}};if budget.fuel==0{original.treasury.return_turn(turn,Default::default())?;return Ok(false)}let result=original.root.admit_step(input,turn.grant);let progress=match &result{Ok((_,progress,_))=>*progress,Err(error)=>error.retained_progress()};original.treasury.return_turn(turn,progress)?;Ok(result?.0)}
 pub fn original_cancelled_now(&self)->Result<bool,ValueError>{let original=self.original.try_lock().map_err(|_|refusal("original Host cancellation supplier is exclusively borrowed"))?;Ok((original.cancelled)())}
 pub fn admit_root_step(&self)->Result<bool,semio_framework_job::OriginalTurnFailure>{let Ok(mut original)=self.original.try_lock()else{return Ok(false)};Self::admit_original_step(&mut original)}
 fn dispatch_original_step<T>(&self,slot:usize,generation:u64,retirement:bool,produce:impl FnOnce(&mut semio_framework_job::StepContext<'_>)->Result<T,semio_framework_job::OriginalTurnFailure>)->Result<Option<T>,semio_framework_job::OriginalTurnFailure>{
  let Ok(mut original)=self.original.try_lock()else{return Ok(None)};
  if !original.root.ready(){Self::admit_original_step(&mut original)?;return Ok(None)}
  if original.checkout.is_none(){let Some(turn)=original.treasury.begin_drive_turn()?else{return Ok(None)};let input=original.root.issued_input(turn.epoch)?;let budget=match original.root.issued_budget(input,turn.grant){Ok(budget)=>budget,Err(error)=>{original.treasury.return_turn(turn,Default::default())?;return Err(error.into())}};if let Err(error)=original.root.begin_turn(slot,generation,input,budget){original.treasury.return_turn(turn,Default::default())?;return Err(error.into())}original.checkout=Some(DriverCheckout::Context{slot,generation,turn});}
  let cancelled=(original.cancelled)();if retirement{original.root.dispatch_cleanup_step(slot,generation,cancelled,produce).map(Some)}else{original.root.dispatch_step(slot,generation,cancelled,produce).map(Some)}
 }
 pub fn dispatch_step<T>(&self,slot:usize,generation:u64,produce:impl FnOnce(&mut semio_framework_job::StepContext<'_>)->Result<T,semio_framework_job::OriginalTurnFailure>)->Result<Option<T>,semio_framework_job::OriginalTurnFailure>{self.dispatch_original_step(slot,generation,false,produce)}
 pub fn dispatch_cleanup_step<T>(&self,slot:usize,generation:u64,produce:impl FnOnce(&mut semio_framework_job::StepContext<'_>)->Result<T,semio_framework_job::OriginalTurnFailure>)->Result<Option<T>,semio_framework_job::OriginalTurnFailure>{self.dispatch_original_step(slot,generation,true,produce)}
 pub fn pending_budget(&self,slot:usize,generation:u64)->Result<semio_framework_actor::OriginalJobBudget,ValueError>{let original=self.original.try_lock().map_err(|_|refusal("original Host root scope is exclusively borrowed"))?;original.root.pending_budget(slot,generation)}
 pub fn hold_pending(&self,slot:usize,generation:u64,budget:semio_framework_actor::OriginalJobBudget)->Result<(),ValueError>{let mut original=self.original.try_lock().map_err(|_|refusal("original Host root scope is exclusively borrowed"))?;original.root.hold_pending(slot,generation,budget)}
 pub fn dispatch_pending_step<T>(&self,slot:usize,generation:u64,budget:semio_framework_actor::OriginalJobBudget,produce:impl FnOnce(&mut semio_framework_job::StepContext<'_>)->Result<T,semio_framework_job::OriginalTurnFailure>)->Result<Option<T>,semio_framework_job::OriginalTurnFailure>{let Ok(mut original)=self.original.try_lock()else{return Ok(None)};let cancelled=(original.cancelled)();original.root.dispatch_pending_step(slot,generation,budget,cancelled,produce).map(Some)}
 pub fn acknowledge_pending(&self,slot:usize,generation:u64,budget:semio_framework_actor::OriginalJobBudget)->Result<(),ValueError>{let mut original=self.original.try_lock().map_err(|_|refusal("original Host root scope is exclusively borrowed"))?;original.root.acknowledge_pending(slot,generation,budget)}
 pub fn checkout_execution_budget(&self,slot:usize,generation:u64,budget:semio_framework_actor::OriginalJobBudget)->Result<semio_framework_actor::OriginalGuestExecutionBudget,ValueError>{let mut original=self.original.try_lock().map_err(|_|refusal("original Host execution scope is exclusively borrowed"))?;original.root.checkout_execution_budget(slot,generation,budget)}
 pub fn receive_execution_receipt(&self,slot:usize,generation:u64,receipt:semio_framework_actor::OriginalGuestExecutionReceipt)->Result<(),ValueError>{let mut original=self.original.try_lock().map_err(|_|refusal("original Host execution scope is exclusively borrowed"))?;original.root.receive_execution_receipt(slot,generation,receipt)}
 pub fn finish_turn(&self,slot:usize,generation:u64)->Result<(semio_framework_actor::RetainedTurnReceipt,u64,u64),ValueError>{let mut original=self.original.try_lock().map_err(|_|refusal("original Host root scope is exclusively borrowed"))?;let Some(DriverCheckout::Context{slot:owned,generation:version,turn})=original.checkout.as_ref()else{return Err(refusal("original Host root has no held context scope"))};if(*owned,*version)!=(slot,generation){return Err(refusal("original Host root finish belongs to another retained slot"))}let turn=*turn;let(receipt,work,execution)=original.root.finish_turn(slot,generation)?;original.treasury.return_turn(turn,receipt.spent)?;original.checkout=None;Ok((receipt,work,execution))}
 pub fn original_remaining(&self)->Result<RetainedCloneGrant,ValueError>{let original=self.original.try_lock().map_err(|_|refusal("original driver treasury is checked out"))?;Ok(original.treasury.original_remaining())}
 pub fn record_admission(&self,progress:RetainedCloneProgress)->Result<(),ValueError>{let mut original=self.original.try_lock().map_err(|_|refusal("original driver treasury is checked out"))?;original.treasury.record_admission(progress)}
 pub fn begin_actor_turn(&self,previous:Option<semio_framework_actor::RetainedTurnReceipt>)->Result<Option<semio_framework_actor::RetainedTurnInput>,ValueError>{let Ok(mut original)=self.original.try_lock()else{return Ok(None)};if !original.root.ready()||original.checkout.is_some(){return Ok(None)}let mut drive=original.treasury.policy().drive;if let Some(previous)=previous{if original.actor_returned!=Some(previous){return Err(refusal("original actor continuation does not own the exact previous receiving receipt"))}drive=intersect(drive,previous.remaining);}let Some(turn)=original.treasury.begin_policy_turn(drive)?else{return Ok(None)};if previous.is_some_and(|previous|previous.input.epoch.checked_add(1)!=Some(turn.epoch)){original.treasury.return_turn(turn,Default::default())?;return Err(refusal("original Actor continuation cannot replace its issued epoch"))}let policy=original.root.policy();let input=original.root.issued_input(turn.epoch)?;let step=match original.root.issued_budget(input,turn.grant){Ok(step)=>step,Err(error)=>{original.treasury.return_turn(turn,Default::default())?;return Err(error)}};if let Err(error)=original.root.begin_actor_scope(input,step){original.treasury.return_turn(turn,Default::default())?;return Err(error)}let budget=semio_framework::kernel::Budget{retained:input,retained_policy:turn.grant,work_fuel:step.fuel,fuel:policy.turn_execution_fuel,deadline_us:step.deadline_us,max_effects:policy.max_effects,max_patch_bytes:policy.max_patch_bytes,max_frames:policy.max_frames};original.checkout=Some(DriverCheckout::Actor{input,turn,budget});original.actor_returned=None;Ok(Some(input))}
 pub fn dispatch_actor_step<T>(&self,input:semio_framework_actor::RetainedTurnInput,produce:impl FnOnce(&mut semio_framework_job::StepContext<'_>)->Result<T,semio_framework_job::OriginalTurnFailure>)->Result<Option<T>,semio_framework_job::OriginalTurnFailure>{let Ok(mut original)=self.original.try_lock()else{return Ok(None)};let Some(DriverCheckout::Actor{input:held,..})=original.checkout.as_ref()else{return Err(refusal("original Actor callback has no held source input").into())};if *held!=input{return Err(refusal("original Actor callback differs from its held source input").into())}let cancelled=(original.cancelled)();original.root.dispatch_actor_step(input,cancelled,produce).map(Some)}
 pub fn dispatch_actor_cleanup_step<T>(&self,input:semio_framework_actor::RetainedTurnInput,produce:impl FnOnce(&mut semio_framework_job::StepContext<'_>)->Result<T,semio_framework_job::OriginalTurnFailure>)->Result<Option<T>,semio_framework_job::OriginalTurnFailure>{let Ok(mut original)=self.original.try_lock()else{return Ok(None)};let Some(DriverCheckout::Actor{input:held,..})=original.checkout.as_ref()else{return Err(refusal("original Actor cleanup has no held source input").into())};if *held!=input{return Err(refusal("original Actor cleanup differs from its held source input").into())}let cancelled=(original.cancelled)();original.root.dispatch_actor_cleanup_step(input,cancelled,produce).map(Some)}
 pub fn checkout_actor_execution_budget(&self,input:semio_framework_actor::RetainedTurnInput)->Result<semio_framework_actor::OriginalGuestExecutionBudget,ValueError>{let mut original=self.original.try_lock().map_err(|_|refusal("original Actor execution source is exclusively borrowed"))?;let Some(DriverCheckout::Actor{input:held,..})=original.checkout.as_ref()else{return Err(refusal("original Actor execution has no held source input"))};if *held!=input{return Err(refusal("original Actor execution differs from its held source input"))}original.root.checkout_actor_execution_budget(input)}
 pub fn receive_actor_execution_receipt(&self,input:semio_framework_actor::RetainedTurnInput,receipt:semio_framework_actor::OriginalGuestExecutionReceipt)->Result<(),ValueError>{let mut original=self.original.try_lock().map_err(|_|refusal("original Actor execution source is exclusively borrowed"))?;original.root.receive_actor_execution_receipt(input,receipt)}
 pub fn actor_budget(&self,input:semio_framework_actor::RetainedTurnInput)->Result<semio_framework::kernel::Budget,ValueError>{let original=self.original.try_lock().map_err(|_|refusal("original Host actor root is exclusively borrowed"))?;let Some(DriverCheckout::Actor{input:held,budget,..})=original.checkout.as_ref()else{return Err(refusal("original Host actor budget has no actual issued input"))};if *held!=input{return Err(refusal("original Host actor budget differs from its exact held input"))}let current=original.root.actor_budget(input)?;Ok(semio_framework::kernel::Budget{retained:current.input,retained_policy:current.retained_policy,work_fuel:current.fuel,..*budget})}
 pub fn close_root_step(&self)->Result<bool,semio_framework_job::OriginalTurnFailure>{let Ok(mut original)=self.original.try_lock()else{return Ok(false)};if original.checkout.is_some(){return Ok(false)}if original.root.terminal_is_empty(){return Ok(true)}let policy=original.treasury.policy().drive;let Some(turn)=original.treasury.begin_policy_turn(policy)?else{return Ok(false)};let input=original.root.issued_input(turn.epoch)?;let result=original.root.close_step(input,turn.grant);let spent=match &result{Ok(step)=>step.progress(),Err(error)=>error.retained_progress()};original.treasury.return_turn(turn,spent)?;result?;Ok(original.root.terminal_is_empty())}
 pub fn finish_actor_step(&self,input:semio_framework_actor::RetainedTurnInput)->Result<semio_framework_actor::RetainedTurnReceipt,semio_framework_job::OriginalTurnFailure>{let mut original=self.original.try_lock().map_err(|_|refusal("original Actor callback is exclusively borrowed"))?;let Some(DriverCheckout::Actor{input:held,turn,..})=original.checkout.as_ref()else{return Err(refusal("original Actor callback has no source checkout").into())};if *held!=input{return Err(refusal("original Actor callback differs from its source checkout").into())}let turn=*turn;let(receipt,_,_)=original.root.finish_actor_scope(input)?;original.treasury.return_turn(turn,receipt.spent)?;original.checkout=None;original.actor_returned=Some(receipt);Ok(receipt)}
 pub fn return_actor_turn(&self,receipt:semio_framework_actor::RetainedTurnReceipt)->Result<bool,semio_framework_job::OriginalTurnFailure>{
  let Ok(mut original)=self.original.try_lock()else{return Ok(false)};let Some(DriverCheckout::Actor{input,turn,..})=original.checkout.as_ref()else{return Err(refusal("original actor retained receipt has no matching treasury checkout").into())};let input=*input;let turn=*turn;receipt.validate_for(original.root.actor_budget(input)?.input)?;let cancelled=(original.cancelled)();original.root.receive_actor_spent(input,receipt.spent,receipt.work_units_spent,cancelled)?;let(actual,_,_)=original.root.finish_actor_scope(input)?;original.treasury.return_turn(turn,actual.spent)?;original.checkout=None;original.actor_returned=Some(receipt);Ok(true)
 }

}
impl GuestRelayWakeReceiptReceiver for GuestRelayWakeDriver{
 fn checkout(&self,slot:usize,generation:u64)->Result<Option<super::GuestRelayWakeTurnGrant>,ValueError>{let Ok(mut original)=self.original.try_lock()else{return Ok(None)};if original.checkout.is_some(){return Ok(None)}let Some(turn)=original.treasury.begin_turn()?else{return Ok(None)};original.checkout=Some(DriverCheckout::Wake{slot,generation,turn});Ok(Some(super::GuestRelayWakeTurnGrant{epoch:turn.epoch,grant:turn.grant}))}
 fn collect(&self,receipt:&crate::GuestRelayWakeReceipt)->Result<bool,ValueError>{
  let Ok(mut original)=self.original.try_lock()else{return Ok(false)};let Some(DriverCheckout::Wake{slot,generation,turn})=original.checkout.as_ref()else{return Err(refusal("original production wake receipt has no treasury checkout"))};let slot=*slot;let generation=*generation;let turn=*turn;let grant=receipt.grant;
  if receipt.slot!=slot||receipt.generation!=generation||receipt.epoch!=turn.epoch||intersect(grant,turn.grant)!=grant||!receipt.progress.fits(grant){return Err(refusal("original production wake receipt does not match its held treasury authority"))}
  original.treasury.return_turn(turn,receipt.progress)?;original.checkout=None;Ok(true)
 }
}
